@@ -1,4 +1,41 @@
+/**
+ * Retry an async operation with configurable policy.
+ *
+ * @param {() => Promise<any>} operation - The async function to call.
+ * @param {object} [options]
+ * @param {number} [options.attempts=3] - Max total calls (positive integer).
+ * @param {(error: any, attempt: number) => boolean} [options.shouldRetry]
+ *   Whether to retry after a failure. `attempt` is one-based for the failed call.
+ * @param {(attempt: number, error: any) => Promise<void>} [options.delay]
+ *   Awaited before each retry. Defaults to no delay.
+ * @returns {Promise<any>}
+ */
 export async function retry(operation, options = {}) {
-  // TODO: implement the contract documented in README.md
-  return operation();
+  const attempts = options.attempts ?? 3;
+  const shouldRetry = options.shouldRetry ?? (() => true);
+  const delay = options.delay ?? (async () => {});
+
+  if (!Number.isInteger(attempts) || attempts <= 0) {
+    throw new TypeError(
+      `attempts must be a positive integer, got ${String(attempts)}`,
+    );
+  }
+
+  let lastError;
+  for (let attempt = 1; attempt <= attempts; attempt++) {
+    try {
+      return await operation();
+    } catch (error) {
+      lastError = error;
+
+      const isLastAttempt = attempt >= attempts;
+      if (isLastAttempt || !shouldRetry(error, attempt)) {
+        throw error;
+      }
+
+      await delay(attempt, error);
+    }
+  }
+
+  throw lastError;
 }

diff --git a/src/ranker.mjs b/src/ranker.mjs
index 65a7daa..9b15fea 100644
--- a/src/ranker.mjs
+++ b/src/ranker.mjs
@@ -1,3 +1,34 @@
 export function rankRoutes(routes, context = {}) {
-  return routes;
+  const ctxTags = Array.isArray(context?.tags) ? context.tags : [];
+  const maxCost = typeof context?.maxCost === 'number' ? context.maxCost : Infinity;
+  const ctxTagSet = new Set(ctxTags);
+
+  const scored = [];
+  for (const route of routes ?? []) {
+    const cost = typeof route?.cost === 'number' ? route.cost : 0;
+    if (cost > maxCost) continue;
+
+    const tags = Array.isArray(route?.tags) ? route.tags : [];
+    const successRate = typeof route?.successRate === 'number' ? route.successRate : 0;
+    const latencyMs = typeof route?.latencyMs === 'number' ? route.latencyMs : 1000;
+
+    let overlap = 0;
+    for (const t of tags) {
+      if (ctxTagSet.has(t)) overlap++;
+    }
+
+    const score =
+      overlap * 4 + successRate * 3 - Math.log1p(latencyMs) / 5 - cost;
+
+    scored.push({ ...route, score });
+  }
+
+  scored.sort((a, b) => {
+    if (b.score !== a.score) return b.score - a.score;
+    const idA = a.id == null ? '' : String(a.id);
+    const idB = b.id == null ? '' : String(b.id);
+    return idA < idB ? -1 : idA > idB ? 1 : 0;
+  });
+
+  return scored;
 }

diff --git a/src/ranker.mjs b/src/ranker.mjs
index 65a7daa..9aa52e5 100644
--- a/src/ranker.mjs
+++ b/src/ranker.mjs
@@ -1,3 +1,19 @@
 export function rankRoutes(routes, context = {}) {
-  return routes;
+  const { tags: ctxTags = [], maxCost = Infinity } = context;
+
+  return routes
+    .filter((r) => (r.cost ?? 0) <= maxCost)
+    .map((r) => {
+      const rTags = r.tags ?? [];
+      const tagOverlap = ctxTags.filter((t) => rTags.includes(t)).length;
+      const score =
+        tagOverlap * 4 +
+        (r.successRate ?? 0) * 3 -
+        Math.log1p(r.latencyMs ?? 1000) / 5 -
+        (r.cost ?? 0);
+      return { ...r, score };
+    })
+    .sort((a, b) =>
+      b.score !== a.score ? b.score - a.score : a.id < b.id ? -1 : a.id > b.id ? 1 : 0
+    );
 }

