diff --git a/src/redact.mjs b/src/redact.mjs
index 991c969..8f44926 100644
--- a/src/redact.mjs
+++ b/src/redact.mjs
@@ -1,10 +1,51 @@
 const SECRET_KEY = /token|secret|password|api[-_]?key/i;

-export function redactSecrets(value) {
-  if (!value || typeof value !== 'object') return value;
-  const output = Array.isArray(value) ? [] : {};
-  for (const [key, child] of Object.entries(value)) {
-    output[key] = SECRET_KEY.test(key) ? '[REDACTED]' : child;
+function isPlainObject(value) {
+  if (value === null || typeof value !== 'object') return false;
+  const proto = Object.getPrototypeOf(value);
+  return proto === Object.prototype || proto === null;
+}
+
+/**
+ * Non-mutating deep redaction of secret-bearing keys.
+ * - Redacts values whose key matches token/secret/password/api[_-]?key (case-insensitive)
+ * - Walks nested plain objects and arrays
+ * - Preserves Date instances, primitives, and other non-plain objects by reference
+ * - Preserves shared references and tolerates cycles via WeakMap memoization
+ * - Copies enumerable data properties only; never invokes getters
+ */
+export function redactSecrets(value, seen = new WeakMap()) {
+  if (value === null || typeof value !== 'object') return value;
+  if (value instanceof Date) return value;
+  if (!Array.isArray(value) && !isPlainObject(value)) return value;
+  if (seen.has(value)) return seen.get(value);
+
+  if (Array.isArray(value)) {
+    const output = [];
+    seen.set(value, output);
+    for (let i = 0; i < value.length; i++) {
+      if (Object.prototype.hasOwnProperty.call(value, i)) {
+        output[i] = redactSecrets(value[i], seen);
+      }
+    }
+    return output;
+  }
+
+  const output = Object.create(Object.getPrototypeOf(value));
+  seen.set(value, output);
+
+  for (const key of Object.keys(value)) {
+    const desc = Object.getOwnPropertyDescriptor(value, key);
+    // Skip missing descriptors and any accessor properties (do not invoke getters)
+    if (!desc || 'get' in desc || 'set' in desc) continue;
+    if (!desc.enumerable) continue;
+
+    if (SECRET_KEY.test(key)) {
+      output[key] = '[REDACTED]';
+    } else {
+      output[key] = redactSecrets(desc.value, seen);
+    }
   }
+
   return output;
 }
